توزيع كود شاشة سلة المشتريات عبر الطبقات الثلاث:
```kotlin
// 1. DOMAIN LAYER (Pure Kotlin - No Frameworks):
data class CartItem(val productId: String, val quantity: Int, val unitPrice: Long)
interface CartRepository {
    fun observeCart(): Flow<List<CartItem>>
    suspend fun updateQuantity(productId: String, quantity: Int)
}
class CalculateCartTotalUseCase {
    operator fun invoke(items: List<CartItem>): Long = items.sumOf { it.quantity * it.unitPrice }
}

// 2. DATA LAYER (Implements Domain contracts, manages SQLite & Network):
class CartRepositoryImpl(
    private val cartDao: CartDao,
    private val api: CartApi
) : CartRepository {
    override fun observeCart(): Flow<List<CartItem>> = cartDao.getCartEntities().map { it.toDomain() }
    override suspend fun updateQuantity(productId: String, quantity: Int) {
        cartDao.update(productId, quantity)
        api.syncCart(productId, quantity)
    }
}

// 3. PRESENTATION LAYER (Translates domain state into observable UI):
@HiltViewModel
class CartViewModel @Inject constructor(
    private val repository: CartRepository,
    private val calculateTotal: CalculateCartTotalUseCase
) : ViewModel() {
    val uiState: StateFlow<CartUiState> = repository.observeCart().map {
        CartUiState.Success(items = it, total = calculateTotal(it))
    }.stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), CartUiState.Loading)
}
```

توضيح انتهاك قاعدة التبعية وكيفية تصحيحه عبر Dependency Inversion:
```kotlin
// ❌ انتهاك صارخ: Domain يعتمد على تفاصيل طبقة Data (Retrofit DTO و Room Entity):
// في module:domain:
class AuthenticateUserUseCase(
    private val api: RetrofitAuthApi // 💥 خطأ كارثي! Domain أصبح يعرف تفاصيل الشبكة الخارجية!
) {
    suspend fun execute(dto: LoginRequestDto): UserEntity { ... }
}

// ✅ تطبيق قاعدة التبعية السليمة: التبعية تشير للداخل والـ Data تعتمد على الـ Domain:
// في module:domain:
interface AuthRepository { // عقد مجرد في قلب الـ Domain
    suspend fun authenticate(credentials: Credentials): Result<User>
}
class AuthenticateUserUseCase(private val authRepository: AuthRepository) {
    suspend fun execute(credentials: Credentials): Result<User> = authRepository.authenticate(credentials)
}

// في module:data (الطبقة الخارجية تعتمد على الـ Domain):
class AuthRepositoryImpl(private val api: RetrofitAuthApi) : AuthRepository {
    override suspend fun authenticate(credentials: Credentials): Result<User> {
        val dto = api.login(credentials.toDto())
        return Result.success(dto.toDomain())
    }
}
```

تطبيق عملي يوضح الفرق بين UseCase يدمج مستودعين و Repository يدير الـ Cache:
```kotlin
// 1. REPOSITORY: يركز على مصادر البيانات والـ Cache:
class UserRepositoryImpl(
    private val localDao: UserDao,
    private val remoteApi: UserApi
) : UserRepository {
    override fun getUser(id: String): Flow<User> = localDao.getUser(id).onStart {
        // استراتيجية مزامنة البيانات والـ Cache:
        refreshUser(id)
    }
    private suspend fun refreshUser(id: String) {
        val networkUser = remoteApi.fetchUser(id)
        localDao.insertUser(networkUser.toEntity())
    }
}

// 2. USE CASE: يركز على سيناريو البيزنس وينسق بين Repositories متعددة:
class UpgradeToPremiumUseCase @Inject constructor(
    private val userRepository: UserRepository,
    private val paymentRepository: PaymentRepository
) {
    suspend operator fun invoke(userId: String, paymentMethodId: String): Result<Subscription> {
        val user = userRepository.getUserSync(userId) ?: return Result.failure(UserNotFoundException())
        if (user.isSuspended) return Result.failure(AccountSuspendedException())

        val chargeResult = paymentRepository.charge(paymentMethodId, PREMIUM_COST_CENTS)
        if (chargeResult.isSuccess) {
            userRepository.markAsPremium(userId)
        }
        return chargeResult
    }
}
```

مثال عملي يوضح الحدود الصارمة للمسؤوليات:
```kotlin
// 1. REPOSITORY: إدارة البيانات والكاش والشبكة فقط:
class OrderRepositoryImpl(private val api: OrderApi, private val dao: OrderDao) : OrderRepository {
    override suspend fun submitOrder(order: Order): Result<OrderConfirmation> = runCatching {
        val response = api.postOrder(order.toDto())
        dao.insertOrder(response.toEntity())
        response.toDomain()
    }
}

// 2. USE CASE: قواعد البيزنس والتحقق والتنسيق بين مستودعين:
class PlaceOrderUseCase @Inject constructor(
    private val orderRepo: OrderRepository,
    private val inventoryRepo: InventoryRepository
) {
    suspend operator fun invoke(order: Order): OrderResult {
        if (order.items.isEmpty()) return OrderResult.Error("Cart is empty")
        val inStock = inventoryRepo.checkStock(order.items)
        if (!inStock) return OrderResult.Error("Items out of stock")
        return orderRepo.submitOrder(order).fold(
            onSuccess = { OrderResult.Success(it) },
            onFailure = { OrderResult.Error(it.message ?: "Submission failed") }
        )
    }
}

// 3. VIEWMODEL: إدارة حالة الواجهة والتفاعل فقط:
@HiltViewModel
class CheckoutViewModel @Inject constructor(
    private val placeOrder: PlaceOrderUseCase
) : ViewModel() {
    private val _uiState = MutableStateFlow<CheckoutUiState>(CheckoutUiState.Idle)
    val uiState: StateFlow<CheckoutUiState> = _uiState.asStateFlow()

    fun onPlaceOrderClicked(order: Order) {
        viewModelScope.launch {
            _uiState.value = CheckoutUiState.Loading
            when (val result = placeOrder(order)) {
                is OrderResult.Success -> _uiState.value = CheckoutUiState.Success(result.confirmation)
                is OrderResult.Error -> _uiState.value = CheckoutUiState.Error(result.message)
            }
        }
    }
}
```

