تطبيق نمط Offline-First بجعل Room هي المصدر الوحيد للحقيقة (SSOT):
```kotlin
class UserRepositoryImpl(
    private val userDao: UserDao,
    private val userApi: UserApi
) : UserRepository {

    // 1. القراءة تتدفق دائماً وحصرياً من الـ SSOT (قاعدة بيانات Room):
    override fun observeUserProfile(userId: String): Flow<User> {
        return userDao.observeUser(userId)
            .map { it.toDomain() }
    }

    // 2. طلب الشبكة يحدث الـ SSOT فقط، والـ SSOT هي التي تخطر الواجهة تلقائياً:
    override suspend fun refreshUserProfile(userId: String): Result<Unit> = runCatching {
        val remoteDto = userApi.fetchUser(userId)
        // كتابة البيانات في Room هي الخطوة الوحيدة؛ انبعاث الـ Flow سيحدث تلقائياً:
        userDao.insertUser(remoteDto.toEntity())
    }
}
```

تطبيق النمطين باحترافية في Jetpack Compose:
```kotlin
// النمط 1: Sealed Interface للشاشات الكاملة المتبادلة حصرياً:
sealed interface ProductListUiState {
    data object Loading : ProductListUiState
    data object Empty : ProductListUiState
    data class Success(val products: ImmutableList<Product>) : ProductListUiState
    data class Error(val message: String) : ProductListUiState
}

@Composable
fun ProductListScreen(uiState: ProductListUiState, onRetry: () -> Unit) {
    when (uiState) {
        is ProductListUiState.Loading -> FullScreenLoadingSpinner()
        is ProductListUiState.Empty -> EmptyStatePlaceholder("No products found")
        is ProductListUiState.Success -> ProductList(uiState.products)
        is ProductListUiState.Error -> ErrorBanner(uiState.message, onRetry = onRetry)
    }
}
